// C# 제네릭
public class Stack<T> {
    private readonly List<T> items = new();

    public void Push(T item) => items.Add(item);
    public T Pop() {
        var last = items[^1];
        items.RemoveAt(items.Count - 1);
        return last;
    }
}

var intStack = new Stack<int>();
intStack.Push(1);
var top = intStack.Pop(); // int

