#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// C는 제네릭을 지원하지 않으므로 매크로나 void* 사용
// 매크로로 타입별 함수 생성
#define DEFINE_STACK(TYPE, NAME) \
    typedef struct { \
        TYPE* data; \
        int size; \
        int capacity; \
    } NAME##_t; \
    \
    NAME##_t* NAME##_new(int capacity) { \
        NAME##_t* stack = malloc(sizeof(NAME##_t)); \
        stack->data = malloc(capacity * sizeof(TYPE)); \
        stack->size = 0; \
        stack->capacity = capacity; \
        return stack; \
    } \
    \
    void NAME##_push(NAME##_t* stack, TYPE value) { \
        if (stack->size < stack->capacity) { \
            stack->data[stack->size++] = value; \
        } \
    } \
    \
    TYPE NAME##_pop(NAME##_t* stack) { \
        return stack->data[--stack->size]; \
    }

// int와 char* 타입용 스택 생성
DEFINE_STACK(int, IntStack)
DEFINE_STACK(char*, StrStack)

int main() {
    // int 스택 사용
    IntStack_t* int_stack = IntStack_new(10);
    IntStack_push(int_stack, 42);
    int value = IntStack_pop(int_stack);

    // char* 스택 사용  
    StrStack_t* str_stack = StrStack_new(10);
    StrStack_push(str_stack, "hello");
    char* str = StrStack_pop(str_stack);

    printf("int: %d, str: %s\n", value, str);
    return 0;
}
